queries.query:
INSERT INTO produto (id, nome, descricao, preco, preco_original, subcategoria_id, ativo, descricao_detalhada, destaque)
VALUES (@Id, @Nome, @Descricao, @Preco, @PrecoOriginal, @SubcategoriaId, @Ativo, @DescricaoDetalhada, @Destaque)
RETURNING id;

INSERT INTO produto_variacao (id, produto_id, cor_id, tamanho_id, estoque, sku, ordem, data_criacao)
VALUES (@Id, @ProdutoId, @CorId, @TamanhoId, @Estoque, @Sku, @Ordem, @DataCriacao)
RETURNING id;

INSERT INTO produto_categoria(nome)
VALUES (@Nome)
RETURNING id;

INSERT INTO produto_subcategoria(nome, categoria_id)
VALUES (@Nome, @CategoriaId)
RETURNING id;

INSERT INTO produto_cor(nome)
VALUES (@Nome)
RETURNING id;

INSERT INTO produto_tamanho(nome, descricao)
VALUES (@Nome, @Descricao)
RETURNING id;

SELECT id AS Id, produto_id AS ProdutoId, nome AS Nome, valor AS Valor
FROM produto_especificacao
WHERE produto_id = @ProdutoId;

SELECT id AS Id, produto_id AS ProdutoId, frete_gratis AS FreteGratis, dias_estimados AS DiasEstimados, custo_envio AS CustoEnvio, politica_devolucao AS PoliticaDevolucao, garantia AS Garantia
FROM produto_informacao_envio
WHERE produto_id = @ProdutoId;

UPDATE produto SET nome = COALESCE(@Nome, nome), descricao = COALESCE(@Descricao, descricao), preco = COALESCE(@Preco, preco), preco_original = COALESCE(@PrecoOriginal, preco_original), descricao_detalhada = COALESCE(@DetailedDescription, descricao_detalhada), destaque = COALESCE(@Featured, destaque), -- subcategoria_id handling skipped for now to keep it simple, or requires name lookup subquery data_atualizacao = NOW() WHERE id = @Id;
-- Specification Update (Delete/Insert) DELETE FROM produto_especificacao WHERE produto_id = @Id AND @SpecificationsJson IS NOT NULL; INSERT INTO produto_especificacao (id, produto_id, nome, valor) SELECT gen_random_uuid(), @Id, s."Name", s."Value" FROM jsonb_to_recordset(@SpecificationsJson::jsonb) AS s("Name" text, "Value" text) WHERE @SpecificationsJson IS NOT NULL;
-- Perfect For Update (Delete/Insert) DELETE FROM produto_perfeito_para WHERE produto_id = @Id AND @PerfectForJson IS NOT NULL; INSERT INTO produto_perfeito_para (id, produto_id, ocasiao) SELECT gen_random_uuid(), @Id, p.value FROM jsonb_array_elements_text(@PerfectForJson::jsonb) AS p WHERE @PerfectForJson IS NOT NULL;
-- Shipping Info Update (Upsert) INSERT INTO produto_informacao_envio (id, produto_id, frete_gratis, dias_estimados, custo_envio, politica_devolucao, garantia) SELECT gen_random_uuid(), @Id, (s->>'FreeShipping')::boolean, (s->>'EstimatedDays')::int, (s->>'ShippingCost')::decimal, s->>'ReturnPolicy', s->>'Warranty' FROM (SELECT @ShippingInfoJson::jsonb as s) as data WHERE @ShippingInfoJson IS NOT NULL ON CONFLICT (produto_id) DO UPDATE SET frete_gratis = EXCLUDED.frete_gratis, dias_estimados = EXCLUDED.dias_estimados, custo_envio = EXCLUDED.custo_envio, politica_devolucao = EXCLUDED.politica_devolucao, garantia = EXCLUDED.garantia;
